// PROBE-06 (03-07-PLAN.md Tasks 1-2): ts_scan's bounded stride-autodetected
// packet walk -- stride detection (188/192/204), resync after corruption,
// the structurally-bounded per-PID table, PCR extraction, PAT/PMT parsing
// with version tracking, and the mux-rate estimate. Behaviors requiring an
// exact hand-computed value (stride confirmation failure, malformed
// adaptation fields, malformed PSI sections, the PCR arithmetic itself)
// use hand-constructed byte buffers built directly in this file, per this
// plan's own instruction; the rest read real fixtures generated by
// scripts/gen_corpus.sh. PROBE-07's continuity-counter carve-outs have
// their own dedicated hand-verified table in test_ts_continuity.cpp.

#include <catch2/catch_test_macros.hpp>

#include <atomic>
#include <chrono>
#include <cstdint>
#include <filesystem>
#include <fstream>
#include <string>
#include <vector>

#include "probe/ts_scan.h"
