using mediadiff::kNullPid;
using mediadiff::kPidCount;
using mediadiff::run_ts_scan;
using mediadiff::TsScanResult;

namespace {

namespace fs = std::filesystem;

fs::path unique_scratch_dir() {
  static std::atomic<int> counter{0};
  const auto now = std::chrono::steady_clock::now().time_since_epoch().count();
  const fs::path dir =
      fs::temp_directory_path() / ("mediadiff_ts_scan_" + std::to_string(now) + "_" + std::to_string(counter++));
  std::error_code ec;
  fs::create_directories(dir, ec);
  return dir;
}

std::string write_bytes(const std::string& name, const std::string& bytes) {
  const fs::path path = unique_scratch_dir() / name;
  std::ofstream out(path, std::ios::binary);
  REQUIRE(out.is_open());
  out.write(bytes.data(), static_cast<std::streamsize>(bytes.size()));
  out.close();
  return path.string();
}

std::string fixture(const std::string& name) { return mediadiff::test::fixture_dir() + "/" + name; }

// Builds one syntactically minimal 188-byte TS packet: sync(1) + header
// bytes (transport_error=0, payload_start, pid) + scrambling/af_control/cc,
// no adaptation field, payload padded to fill the remaining 184 bytes.
// `pusi` is payload_unit_start_indicator; `payload_prefix` (if non-empty) is
// placed at the very start of the payload (e.g. a PSI pointer_field +
// section), the rest padded with 0xFF stuffing.
std::string build_packet(int pid, std::uint8_t cc, bool pusi, const std::string& payload_prefix = "",
                          std::uint8_t af_control = 0x1, const std::string& adaptation_field = "") {
  std::string packet;
  packet.push_back(static_cast<char>(0x47));
  const std::uint8_t b1 = static_cast<std::uint8_t>((pusi ? 0x40 : 0x00) | ((pid >> 8) & 0x1F));
  packet.push_back(static_cast<char>(b1));
  packet.push_back(static_cast<char>(pid & 0xFF));
  const std::uint8_t b3 = static_cast<std::uint8_t>((af_control << 4) | (cc & 0x0F));
  packet.push_back(static_cast<char>(b3));
  if (af_control == 0x2 || af_control == 0x3) {
    packet.push_back(static_cast<char>(adaptation_field.size()));
    packet += adaptation_field;
  }
  packet += payload_prefix;
  packet.resize(188, static_cast<char>(0xFF));
  REQUIRE(packet.size() == 188);
  return packet;
}

std::string be16(int v) {
  std::string s(2, '\0');
  s[0] = static_cast<char>((v >> 8) & 0xFF);
  s[1] = static_cast<char>(v & 0xFF);
  return s;
}

// Stride detection requires kStrideConfirmCount (5) consecutive sync bytes
// -- every hand-built buffer below that constructs fewer than 5 packets of
// its own pads out to 5 with plain payload-only filler packets on a PID
// none of these tests inspect, purely so `stride == 188` is confirmable at
// all before the behavior under test can be observed.
std::string pad_to_min_packets(const std::string& buf, int min_packets) {
  std::string padded = buf;
  int have = static_cast<int>(buf.size() / 188);
  for (int i = have; i < min_packets; ++i) {
    padded += build_packet(0x0199, static_cast<std::uint8_t>(i), /*pusi=*/false);
  }
  return padded;
}

}  // namespace

